#!/usr/bin/env node
/**
 * Test-only harness: checks that the TypeScript engine and the Java generated by the MCreator
 * compiler produce the same heights for every supported noise type.
 *
 * Usage: node mcreator-plugin/tests/run-parity.mjs [--mcreator "<MCreator install>"]
 *
 * The MCreator install is discovered the same way as in run-tests.mjs: an explicit --mcreator path,
 * MCREATOR_HOME, the repo-local unpacked runtime, then the usual install locations. The Gradle cache
 * that holds the Minecraft/NeoForge artifacts comes from MCREATOR_GRADLE_CACHE, or from
 * `~/.mcreator/gradle/caches`.
 */
import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { pathToFileURL } from 'node:url'

const root = process.cwd()
const args = process.argv.slice(2)
const argValue = (name) => {
  const index = args.indexOf(name)
  return index >= 0 ? args[index + 1] : undefined
}

const unpacked = path.join(root, '.freebuff', 'mcreator-runtime', 'unpacked')
const localRuntimes = fs.existsSync(unpacked)
  ? fs.readdirSync(unpacked).map((entry) => path.join(unpacked, entry)).filter((dir) => fs.existsSync(path.join(dir, 'mcreator.exe')))
  : []
const install = [
  argValue('--mcreator'),
  process.env.MCREATOR_HOME,
  ...localRuntimes,
  'C:\\Program Files\\MCreator',
  'C:\\Program Files (x86)\\MCreator',
  path.join(os.homedir(), 'AppData', 'Local', 'Programs', 'MCreator'),
].filter(Boolean)
  .map((directory) => path.resolve(directory))
  .find((directory) => fs.existsSync(path.join(directory, 'mcreator.exe')))
if (!install) throw new Error('MCreator installation not found. Pass --mcreator "<directory containing mcreator.exe>" or set MCREATOR_HOME.')

const executable = (name) => path.join(install, 'jdk', 'bin', process.platform === 'win32' ? `${name}.exe` : name)
const javac = executable('javac')
const java = executable('java')

const work = path.join(root, '.freebuff', 'plugin-build', 'parity')
const engineOut = path.join(root, '.freebuff', 'plugin-build', 'engine-js')
const pluginLink = path.join(root, 'mcreator-plugin', 'dist', 'terrain-studio.zip')
const mcLibs = path.join(install, 'lib')

// MCreator resolves the Minecraft and NeoForge artifacts inside the user profile's Gradle cache.
const gradleCache = process.env.MCREATOR_GRADLE_CACHE
  ? path.resolve(process.env.MCREATOR_GRADLE_CACHE)
  : path.join(os.homedir(), '.mcreator', 'gradle', 'caches')

function run(command, args, options = {}) {
  const result = spawnSync(command, args, { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, ...options })
  if (result.status !== 0) {
    console.error(result.stdout ?? '')
    console.error(result.stderr ?? '')
    throw new Error(`${path.basename(command)} failed with ${result.status}`)
  }
  return result.stdout
}

// Compile the engine so Node can import the exact module the app uses.
fs.rmSync(engineOut, { recursive: true, force: true })
run(process.execPath, [path.join(root, 'node_modules', 'typescript', 'bin', 'tsc'),
  'src/terrainEngine.ts', '--outDir', engineOut, '--module', 'es2022', '--target', 'es2022',
  '--moduleResolution', 'bundler', '--skipLibCheck',
])
const engine = await import(pathToFileURL(path.join(engineOut, 'terrainEngine.js')).href)

function classpath() {
  const jars = []
  const walk = (directory, depth = 0) => {
    if (depth > 8 || !fs.existsSync(directory)) return
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      const full = path.join(directory, entry.name)
      if (entry.isDirectory()) walk(full, depth + 1)
      else if (/\.jar$/i.test(entry.name) && !/(sources|javadoc|userdev|stubs|native)/i.test(entry.name)) jars.push(full)
    }
  }
  walk(path.join(gradleCache, 'modules-2', 'files-2.1'))
  const neoform = path.join(gradleCache, 'neoformruntime', 'intermediate_results')
  if (fs.existsSync(neoform)) {
    for (const entry of fs.readdirSync(neoform)) {
      if (entry.startsWith('recompile_') && entry.endsWith('_output.jar')) jars.push(path.join(neoform, entry))
    }
  }
  return { jars, classpath: jars.join(path.delimiter) }
}
const { classpath: minecraftClasspath, jars } = classpath()
if (jars.length === 0) throw new Error('No Minecraft/NeoForge artifacts found for the parity harness.')
const pluginClasspath = [pluginLink, path.join(mcLibs, '*')].join(path.delimiter)

// Compile the test-only compiler CLI once.
const toolDir = path.join(work, 'tool')
fs.mkdirSync(toolDir, { recursive: true })
run(javac, ['-encoding', 'UTF-8', '-classpath', pluginClasspath, '-d', toolDir,
  path.join('mcreator-plugin', 'tests', 'NoiseParityTool.java')])

const types = ['value', 'ridged', 'perlin', 'simplex', 'cellular', 'wave',
  'minecraft-continentalness', 'minecraft-erosion', 'minecraft-weirdness', 'minecraft-temperature']
const size = 5, extent = 4000, world = { minY: -64, maxY: 319, seaLevel: 63 }
const coordinates = []
for (let row = 0; row < size; row += 1) {
  const z = (row / (size - 1) - 0.5) * extent
  for (let col = 0; col < size; col += 1) coordinates.push([(col / (size - 1) - 0.5) * extent, z])
}

let failures = 0
for (const type of types) {
  const directory = path.join(work, type)
  const out = path.join(directory, 'out')
  fs.rmSync(directory, { recursive: true, force: true })
  fs.mkdirSync(out, { recursive: true })
  const project = {
    format: 'terrain-studio', version: 1, name: type,
    world: { minY: -64, maxY: 319, seaLevel: 63 },
    graph: {
      nodes: [
        { id: 'c', data: { kind: 'coordinates' } },
        { id: 'n', data: { kind: 'noise', noiseType: type, scale: 0.004, amplitude: 0.8, seed: 137 } },
        { id: 'o', data: { kind: 'output' } },
      ],
      edges: [{ id: '1', source: 'c', target: 'n' }, { id: '2', source: 'n', target: 'o' }],
    },
  }
  const projectFile = path.join(directory, 'project.terrain')
  fs.writeFileSync(projectFile, JSON.stringify(project))
  run(java, ['-classpath', [toolDir, pluginClasspath].join(path.delimiter),
    'NoiseParityTool', projectFile, out, 'terrain_test', 'neoforge-26.1.2', 'TerrainStudioWorldgen'])

  const classes = path.join(directory, 'classes')
  fs.mkdirSync(classes, { recursive: true })
  const source = path.join(out, 'src', 'main', 'java', 'net', 'terrainstudio', 'generated', 'TerrainStudioWorldgen.java')
  const runner = path.join(directory, 'Heights.java')
  fs.writeFileSync(runner, `public class Heights {
    public static void main(String[] args) {
        double[][] points = { ${coordinates.map(([x, z]) => `{${x}, ${z}}`).join(', ')} };
        for (double[] point : points) System.out.println(net.terrainstudio.generated.TerrainStudioWorldgen.height(point[0], point[1]));
    }
}
`)
  run(javac, ['-encoding', 'UTF-8', '-classpath', minecraftClasspath, '-d', classes, source, runner])
  const output = run(java, ['-classpath', [classes, minecraftClasspath].join(path.delimiter), 'Heights'])
    .trim().split(/\r?\n/).map(Number)

  const graph = {
    version: 1,
    nodes: [
      { id: 'c', kind: 'coordinates', title: 'Coordinates' },
      { id: 'n', kind: 'noise', title: 'Noise', noiseType: type, scale: 0.004, amplitude: 0.8, seed: 137 },
      { id: 'o', kind: 'output', title: 'Output' },
    ],
    edges: [{ id: '1', source: 'c', target: 'n' }, { id: '2', source: 'n', target: 'o' }],
  }
  const ts = engine.evaluateHeightField(graph, world, size, extent).values
  // The preview stores a Float32 height field, so compare in normalised 0..1 space, not block heights.
  const span = world.maxY - world.minY
  let worst = 0
  for (let i = 0; i < coordinates.length; i += 1) {
    worst = Math.max(worst, Math.abs((ts[i] - world.minY) / span - (output[i] - world.minY) / span))
  }
  const ok = worst < 1e-5
  if (!ok) failures += 1
  console.log(`${ok ? 'PASS' : 'FAIL'} ${type.padEnd(26)} max |TS - Java| = ${worst.toExponential(3)}  (sample ${output[0].toFixed(6)})`)
}

// Shaping nodes: domain warp, clamp, remap, curve, blend, terrace and erosion must match too.
const shapingNodes = [
  { id: 'c', kind: 'coordinates', title: 'Coordinates' },
  { id: 'w', kind: 'warp', title: 'Warp', scale: 0.004, strength: 25, seed: 11, rotation: 15 },
  { id: 'n1', kind: 'noise', title: 'Noise A', noiseType: 'perlin', scale: 0.006, amplitude: 0.9, seed: 7, rotation: 30 },
  { id: 'n2', kind: 'noise', title: 'Noise B', noiseType: 'ridged', scale: 0.003, amplitude: 0.5, seed: 9 },
  { id: 'cl', kind: 'clamp', title: 'Clamp', min: 0.1, max: 0.9 },
  { id: 'rm', kind: 'remap', title: 'Remap', inMin: 0.1, inMax: 0.9, outMin: 0, outMax: 1 },
  { id: 'cv', kind: 'curve', title: 'Curve', gamma: 1.4 },
  { id: 'bl', kind: 'blend', title: 'Blend', factor: 0.6 },
  { id: 'te', kind: 'terrace', title: 'Terrace', steps: 6, strength: 0.7 },
  { id: 'er', kind: 'erosion', title: 'Erosion', scale: 0.02, strength: 0.4, seed: 31 },
  { id: 'o', kind: 'output', title: 'Output' },
]
const shapingEdges = [
  { id: '1', source: 'c', target: 'w' }, { id: '2', source: 'w', target: 'n1' },
  { id: '3', source: 'c', target: 'n2' }, { id: '4', source: 'n1', target: 'cl' },
  { id: '5', source: 'cl', target: 'rm' }, { id: '6', source: 'rm', target: 'cv' },
  { id: '7', source: 'cv', target: 'bl' }, { id: '8', source: 'n2', target: 'bl' },
  { id: '9', source: 'bl', target: 'te' }, { id: '10', source: 'te', target: 'er' },
  { id: '11', source: 'er', target: 'o' },
]
const shapingWorld = { ...world, seed: 5 }
const shapingDirectory = path.join(work, 'shaping')
const shapingOut = path.join(shapingDirectory, 'out')
fs.rmSync(shapingDirectory, { recursive: true, force: true })
fs.mkdirSync(shapingOut, { recursive: true })
const shapingProject = {
  format: 'terrain-studio', version: 1, name: 'shaping', world: shapingWorld,
  graph: {
    nodes: shapingNodes.map((node) => ({
      id: node.id,
      data: { kind: node.kind, title: node.title, noiseType: node.noiseType, scale: node.scale, amplitude: node.amplitude,
        seed: node.seed, factor: node.factor, min: node.min, max: node.max, inMin: node.inMin, inMax: node.inMax,
        outMin: node.outMin, outMax: node.outMax, gamma: node.gamma, steps: node.steps, strength: node.strength, rotation: node.rotation },
    })),
    edges: shapingEdges,
  },
}
const shapingFile = path.join(shapingDirectory, 'project.terrain')
fs.writeFileSync(shapingFile, JSON.stringify(shapingProject))
run(java, ['-classpath', [toolDir, pluginClasspath].join(path.delimiter),
  'NoiseParityTool', shapingFile, shapingOut, 'terrain_test', 'neoforge-26.1.2', 'TerrainStudioWorldgen'])
const shapingClasses = path.join(shapingDirectory, 'classes')
fs.mkdirSync(shapingClasses, { recursive: true })
const shapingSource = path.join(shapingOut, 'src', 'main', 'java', 'net', 'terrainstudio', 'generated', 'TerrainStudioWorldgen.java')
const shapingRunner = path.join(shapingDirectory, 'Heights.java')
fs.writeFileSync(shapingRunner, `public class Heights {
    public static void main(String[] args) {
        double[][] points = { ${coordinates.map(([x, z]) => `{${x}, ${z}}`).join(', ')} };
        for (double[] point : points) System.out.println(net.terrainstudio.generated.TerrainStudioWorldgen.height(point[0], point[1]));
    }
}
`)
run(javac, ['-encoding', 'UTF-8', '-classpath', minecraftClasspath, '-d', shapingClasses, shapingSource, shapingRunner])
const shapingOutput = run(java, ['-classpath', [shapingClasses, minecraftClasspath].join(path.delimiter), 'Heights'])
  .trim().split(/\r?\n/).map(Number)
const shapingTs = engine.evaluateHeightField({ version: 1, nodes: shapingNodes, edges: shapingEdges }, shapingWorld, size, extent).values
const shapingSpan = shapingWorld.maxY - shapingWorld.minY
let shapingWorst = 0
for (let i = 0; i < coordinates.length; i += 1) {
  shapingWorst = Math.max(shapingWorst, Math.abs((shapingTs[i] - shapingWorld.minY) / shapingSpan - (shapingOutput[i] - shapingWorld.minY) / shapingSpan))
}
const shapingOk = shapingWorst < 1e-5
if (!shapingOk) failures += 1
console.log(`${shapingOk ? 'PASS' : 'FAIL'} shaping-nodes              max |TS - Java| = ${shapingWorst.toExponential(3)}  (sample ${shapingOutput[0].toFixed(6)})`)

// Every arithmetic node added to the palette must compile to the same height in both languages.
function parityCase(name, nodes, edges, caseWorld = world) {
  const directory = path.join(work, name)
  const out = path.join(directory, 'out')
  fs.rmSync(directory, { recursive: true, force: true })
  fs.mkdirSync(out, { recursive: true })
  const project = {
    format: 'terrain-studio', version: 1, name, world: caseWorld,
    graph: {
      nodes: nodes.map(({ id, ...rest }) => ({ id, data: rest })),
      edges,
    },
  }
  const projectFile = path.join(directory, 'project.terrain')
  fs.writeFileSync(projectFile, JSON.stringify(project))
  run(java, ['-classpath', [toolDir, pluginClasspath].join(path.delimiter),
    'NoiseParityTool', projectFile, out, 'terrain_test', 'neoforge-26.1.2', 'TerrainStudioWorldgen'])

  const classes = path.join(directory, 'classes')
  fs.mkdirSync(classes, { recursive: true })
  const source = path.join(out, 'src', 'main', 'java', 'net', 'terrainstudio', 'generated', 'TerrainStudioWorldgen.java')
  const runner = path.join(directory, 'Heights.java')
  fs.writeFileSync(runner, `public class Heights {
    public static void main(String[] args) {
        double[][] points = { ${coordinates.map(([x, z]) => `{${x}, ${z}}`).join(', ')} };
        for (double[] point : points) System.out.println(net.terrainstudio.generated.TerrainStudioWorldgen.height(point[0], point[1]));
    }
}
`)
  run(javac, ['-encoding', 'UTF-8', '-classpath', minecraftClasspath, '-d', classes, source, runner])
  const output = run(java, ['-classpath', [classes, minecraftClasspath].join(path.delimiter), 'Heights'])
    .trim().split(/\r?\n/).map(Number)

  const ts = engine.evaluateHeightField({ version: 1, nodes, edges }, caseWorld, size, extent).values
  const span = caseWorld.maxY - caseWorld.minY
  let worst = 0
  for (let i = 0; i < coordinates.length; i += 1) {
    worst = Math.max(worst, Math.abs((ts[i] - caseWorld.minY) / span - (output[i] - caseWorld.minY) / span))
  }
  const ok = worst < 1e-5
  if (!ok) failures += 1
  console.log(`${ok ? 'PASS' : 'FAIL'} ${name.padEnd(26)} max |TS - Java| = ${worst.toExponential(3)}  (sample ${output[0].toFixed(6)})`)
}

const extendedNodes = [
  { id: 'c', kind: 'coordinates', title: 'Coordinates' },
  { id: 'sw', kind: 'swirl', title: 'Swirl', strength: 140, scale: 0.01 },
  { id: 'rd', kind: 'radial', title: 'Radial', scale: 0.02 },
  { id: 'n1', kind: 'noise', title: 'Noise A', noiseType: 'perlin', scale: 0.006, amplitude: 0.9, seed: 7 },
  { id: 'n2', kind: 'noise', title: 'Noise B', noiseType: 'wave', scale: 0.01, amplitude: 0.8, seed: 13 },
  { id: 'mn', kind: 'min', title: 'Minimum' },
  { id: 'mx', kind: 'max', title: 'Maximum' },
  { id: 'sb', kind: 'subtract', title: 'Subtract' },
  { id: 'pw', kind: 'power', title: 'Power', exponent: 1.5 },
  { id: 'ab', kind: 'abs', title: 'Absolute' },
  { id: 'iv', kind: 'invert', title: 'Invert' },
  { id: 'dv', kind: 'divide', title: 'Divide' },
  { id: 'sm', kind: 'smoothstep', title: 'Smoothstep', inMin: 0.2, inMax: 0.8 },
  { id: 'th', kind: 'threshold', title: 'Threshold', threshold: 0.45, strength: 0.1 },
  { id: 'th2', kind: 'threshold', title: 'Hard Threshold', threshold: 0.5, strength: 0 },
  { id: 'bl', kind: 'blend', title: 'Blend', factor: 0.5 },
  { id: 'of', kind: 'offset', title: 'Offset', factor: 1.7, bias: -0.2 },
  { id: 'rg', kind: 'ridge', title: 'Ridge' },
  { id: 'sn', kind: 'sine', title: 'Sine', scale: 1.5, seed: 3 },
  { id: 'tr', kind: 'triangle', title: 'Triangle', scale: 1.2, seed: 5 },
  { id: 'qz', kind: 'quantize', title: 'Quantize', steps: 12 },
  { id: 'ct', kind: 'contrast', title: 'Contrast', contrast: 1.3 },
  { id: 'bl2', kind: 'blend', title: 'Blend 2', factor: 0.35 },
  { id: 'te', kind: 'terrace', title: 'Terrace', steps: 5, strength: 0.6 },
  { id: 'o', kind: 'output', title: 'Output' },
]
const extendedEdges = [
  { id: '1', source: 'c', target: 'sw' }, { id: '2', source: 'sw', target: 'rd' },
  { id: '3', source: 'sw', target: 'n1' }, { id: '4', source: 'c', target: 'n2' },
  { id: '5', source: 'n1', target: 'mn' }, { id: '6', source: 'n2', target: 'mn' },
  { id: '7', source: 'mn', target: 'mx' }, { id: '8', source: 'rd', target: 'mx' },
  { id: '9', source: 'mx', target: 'sb' }, { id: '10', source: 'n2', target: 'sb' },
  { id: '11', source: 'sb', target: 'pw' }, { id: '12', source: 'sb', target: 'ab' },
  { id: '13', source: 'ab', target: 'iv' }, { id: '14', source: 'mx', target: 'dv' },
  { id: '15', source: 'pw', target: 'dv' }, { id: '16', source: 'iv', target: 'sm' },
  { id: '17', source: 'sm', target: 'th' }, { id: '18', source: 'n1', target: 'th2' },
  { id: '19', source: 'th', target: 'bl' }, { id: '20', source: 'th2', target: 'bl' },
  { id: '21', source: 'bl', target: 'of' }, { id: '22', source: 'of', target: 'rg' },
  { id: '23', source: 'rg', target: 'sn' }, { id: '24', source: 'sn', target: 'tr' },
  { id: '25', source: 'tr', target: 'qz' }, { id: '26', source: 'qz', target: 'ct' },
  { id: '27', source: 'ct', target: 'bl2' }, { id: '28', source: 'dv', target: 'bl2' },
  { id: '29', source: 'bl2', target: 'te' }, { id: '30', source: 'te', target: 'o' },
]
parityCase('extended-nodes', extendedNodes, extendedEdges, { ...world, seed: 9 })

// A custom texture is inlined before compilation, so its bread-and-butter noise must match too.
const textureGraph = {
  version: 1,
  nodes: [
    { id: 'tc', kind: 'coordinates', title: 'Texture Coordinates' },
    { id: 'tn', kind: 'noise', title: 'Texture Noise', noiseType: 'perlin', scale: 0.012, amplitude: 1, seed: 44 },
    { id: 'to', kind: 'output', title: 'Texture Output' },
  ],
  edges: [{ id: 't1', source: 'tc', target: 'tn' }, { id: 't2', source: 'tn', target: 'to' }],
}
const textureEngine = await import(pathToFileURL(path.join(engineOut, 'terrainEngine.js')).href)
const flatTexture = textureEngine.flattenCustomTextures(
  {
    version: 1,
    nodes: [
      { id: 'c', kind: 'coordinates', title: 'Coordinates' },
      { id: 't', kind: 'noise', title: 'Texture', noiseType: 'custom', textureId: 'tex-1', scale: 0.004, amplitude: 1, seed: 0 },
      { id: 'o', kind: 'output', title: 'Output' },
    ],
    edges: [{ id: '1', source: 'c', target: 't' }, { id: '2', source: 't', target: 'o' }],
  },
  [{ id: 'tex-1', name: 'Texture', graph: textureGraph }],
)
parityCase('custom-texture', flatTexture.nodes, flatTexture.edges, { ...world, seed: 2 })

// Graph validation: bad nodes must be rejected even when they are not connected to the output.
const guarded = (extra) => ({
  version: 1,
  nodes: [
    { id: 'c', kind: 'coordinates', title: 'Coordinates' },
    { id: 'n', kind: 'noise', title: 'Noise', noiseType: 'value', scale: 0.01, amplitude: 1, seed: 1 },
    { id: 'a', kind: 'add', title: 'Add' },
    { id: 'o', kind: 'output', title: 'Output' },
    ...extra,
  ],
  edges: [
    { id: '1', source: 'c', target: 'n' },
    { id: '2', source: 'n', target: 'a' },
    { id: '3', source: 'a', target: 'o' },
  ],
})
const rejected = [
  { id: 'bad-type', kind: 'noise', title: 'Disconnected', noiseType: 'not-a-noise', scale: 0.01, amplitude: 1, seed: 1 },
  { id: 'bad-scale', kind: 'noise', title: 'Disconnected', noiseType: 'perlin', scale: -1, amplitude: 1, seed: 1 },
  { id: 'bad-factor', kind: 'multiply', title: 'Disconnected', factor: Number.NaN },
]
for (const node of rejected) {
  try {
    engine.compileGraph(guarded([node]))
    console.log(`FAIL engine validation accepted ${node.id}`)
    failures += 1
  } catch {
    console.log(`PASS engine rejects disconnected ${node.id}`)
  }
}

fs.rmSync(path.join(work, 'tool'), { recursive: true, force: true })
if (failures > 0) {
  console.error(`${failures} noise type(s) differ between the preview engine and the MCreator compiler`)
  process.exit(1)
}
console.log('PASS all noise types match between src/terrainEngine.ts and generated Java')
